namespace Invex.Atom.Module.GitVersion.Tests;

[TestFixture]
internal sealed class ProductGitVersionConfigTests
{
    private const string RootConfig =
        "\uFEFFmode: ContinuousDelivery\r\ntag-prefix: '[vV]?'\r\n\r\nignore:\r\n  sha: [ abc ]\r\n\r\n# Branches\r\nbranches:\r\n  main:\r\n    regex: ^main$\r\n";

    private const string ExpectedAppAConfig = """
        # Generated by Atom for the product 'AppA'. Do not edit: run 'atom gen' to update it.
        # Settings: the root GitVersion.yml, with this product's tag prefix and ignored paths.

        mode: ContinuousDelivery

        # Branches
        branches:
          main:
            regex: ^main$

        tag-prefix: 'appa/v'
        ignore:
          paths:
            - '^(?!(?:src[/\\]AppA[/\\].*|src[/\\]Shared[/\\].*|global\.json|Directory\.Build\.[^/\\]*|Directory\.Packages\.[^/\\]*|_atom[/\\].*|\.github[/\\]workflows[/\\].*|\.devops[/\\]workflows[/\\].*)$).*'

        """;

    private static string Root =>
        Environment.OSVersion.Platform is PlatformID.Win32NT
            ? @"C:\Atom"
            : "/Atom";

    private static (IHost Host, MockFileSystem FileSystem) CreateHost(
        bool headless = false,
        bool gen = false,
        string? rootConfig = RootConfig,
        string? product = null,
        string? gitVersionConfig = null,
        bool gitRepository = true)
    {
        var fileSystem = FileSystemUtils.DefaultMockFileSystem;

        if (gitRepository)
            fileSystem.AddDirectory(fileSystem.Path.Combine(Root, ".git"));

        if (rootConfig is not null)
            fileSystem.AddFile(fileSystem.Path.Combine(Root, "GitVersion.yml"), new(rootConfig));

        IArg[] args = [new CommandArg(gen ? "Gen" : "SomeTarget"), .. headless ? [new HeadlessArg()] : Array.Empty<IArg>()];

        var host = CreateTestHost<GitVersionProductsTestBuild>(fileSystem: fileSystem,
            commandLineArgs: new(true, args),
            configure: builder =>
            {
                var values = new Dictionary<string, string?>();

                if (product is not null)
                    values["Params:product"] = product;

                if (gitVersionConfig is not null)
                    values["Params:gitversion-config"] = gitVersionConfig;

                builder.Configuration.AddInMemoryCollection(values);
            });

        return (host, fileSystem);
    }

    private static IAtomLifecycleHook GetHook(IHost host) =>
        host
            .Services
            .GetServices<IAtomLifecycleHook>()
            .OfType<ProductGitVersionConfigHook>()
            .ShouldHaveSingleItem();

    private static string ConfigPath(MockFileSystem fileSystem, string product) =>
        fileSystem.Path.Combine(Root, "src", product, "GitVersion.yml");

    [Test]
    public async Task BeforeExecute_WhenNotHeadless_WritesEachProductConfig()
    {
        var (host, fileSystem) = CreateHost();

        await GetHook(host)
            .BeforeExecute(CancellationToken.None);

        fileSystem
            .File
            .ReadAllText(ConfigPath(fileSystem, "AppA"))
            .ReplaceLineEndings("\n")
            .ShouldBe(ExpectedAppAConfig);

        var appB = fileSystem
            .File
            .ReadAllText(ConfigPath(fileSystem, "AppB"))
            .ReplaceLineEndings("\n");

        appB.ShouldContain("tag-prefix: 'app\\.b/v'\n");
        appB.ShouldContain(@"    - '^(?!(?:src[/\\]AppB[/\\].*|global\.json|");

        fileSystem
            .FileExists(fileSystem.Path.Combine(Root, "src", "Shared", "GitVersion.yml"))
            .ShouldBeFalse();
    }

    [Test]
    public async Task BeforeExecute_WithoutRootConfig_WritesOnlyProductSettings()
    {
        var (host, fileSystem) = CreateHost(rootConfig: null);

        await GetHook(host)
            .BeforeExecute(CancellationToken.None);

        var appA = fileSystem
            .File
            .ReadAllText(ConfigPath(fileSystem, "AppA"))
            .ReplaceLineEndings("\n");

        appA.ShouldStartWith("""
            # Generated by Atom for the product 'AppA'. Do not edit: run 'atom gen' to update it.
            # Settings: GitVersion's defaults, with this product's tag prefix and ignored paths.

            tag-prefix: 'appa/v'
            ignore:
              paths:

            """);
    }

    [Test]
    public async Task BeforeExecute_WhenHeadlessAndOutdated_Throws()
    {
        var (host, fileSystem) = CreateHost(true);

        fileSystem.AddFile(ConfigPath(fileSystem, "AppA"), new(ExpectedAppAConfig + "# edited\n"));

        var exception = await Should.ThrowAsync<AtomException>(() => GetHook(host)
            .BeforeExecute(CancellationToken.None));

        exception.Message.ShouldBe(
            "The GitVersion configuration of one or more products is out of date: 'src/AppA/GitVersion.yml', 'src/AppB/GitVersion.yml'. To regenerate it, run the 'Gen' target.");

        fileSystem
            .File
            .ReadAllText(ConfigPath(fileSystem, "AppA"))
            .ShouldEndWith("# edited\n");
    }

    [Test]
    public async Task BeforeExecute_WhenHeadlessAndNoRepository_DoesNotCheck()
    {
        var (host, _) = CreateHost(true, gitRepository: false);

        await Should.NotThrowAsync(() => GetHook(host)
            .BeforeExecute(CancellationToken.None));
    }

    [Test]
    public async Task BeforeExecute_WhenHeadlessAndUpToDate_DoesNothing()
    {
        var (writeHost, fileSystem) = CreateHost();

        await GetHook(writeHost)
            .BeforeExecute(CancellationToken.None);

        // CRLF line endings and a byte order mark don't count as drift
        var appAPath = ConfigPath(fileSystem, "AppA");
        fileSystem.File.WriteAllText(appAPath, "\uFEFF" + fileSystem.File.ReadAllText(appAPath).ReplaceLineEndings("\r\n"));

        var checkHost = CreateTestHost<GitVersionProductsTestBuild>(fileSystem: fileSystem,
            commandLineArgs: new(true, [new CommandArg("SomeTarget"), new HeadlessArg()]));

        await Should.NotThrowAsync(() => GetHook(checkHost)
            .BeforeExecute(CancellationToken.None));
    }

    [Test]
    public async Task BeforeExecute_WhenHeadlessGen_Writes()
    {
        var (host, fileSystem) = CreateHost(true, true);

        await GetHook(host)
            .BeforeExecute(CancellationToken.None);

        fileSystem
            .FileExists(ConfigPath(fileSystem, "AppA"))
            .ShouldBeTrue();
    }

    [Test]
    public async Task BeforeExecute_WithInvalidProducts_WarnsLocallyAndThrowsHeadless()
    {
        var (localHost, localFileSystem) = CreateHost();
        ((GitVersionProductsTestBuild)localHost.Services.GetRequiredService<IBuildDefinition>()).TestProducts =
        [
            new("AppA")
            {
                Paths = ["src/AppA/**"],
                DependsOn = ["Missing"],
                GitVersionConfig = "src/AppA/GitVersion.yml",
            },
        ];

        await Should.NotThrowAsync(() => GetHook(localHost)
            .BeforeExecute(CancellationToken.None));

        localFileSystem
            .FileExists(ConfigPath(localFileSystem, "AppA"))
            .ShouldBeFalse();

        var (headlessHost, _) = CreateHost(true);
        ((GitVersionProductsTestBuild)headlessHost.Services.GetRequiredService<IBuildDefinition>()).TestProducts =
        [
            new("AppA")
            {
                Paths = ["src/AppA/**"],
                DependsOn = ["Missing"],
                GitVersionConfig = "src/AppA/GitVersion.yml",
            },
        ];

        (await Should.ThrowAsync<AtomException>(() => GetHook(headlessHost)
                .BeforeExecute(CancellationToken.None)))
            .Message
            .ShouldContain("Product 'AppA' depends on unknown product 'Missing'.");
    }

    [TestCase("GitVersion.yml", true, "GitVersion.yml")]
    [TestCase("./.gitversion.YAML", true, ".gitversion.YAML")]
    [TestCase(".GitVersion.yml", false, ".GitVersion.yml")]
    public void GetExpectedConfigs_WhenProductConfigIsARootConfig_Throws(string config, bool hasRootConfig, string fileName)
    {
        var (host, _) = CreateHost(rootConfig: hasRootConfig
            ? RootConfig
            : null);

        ((GitVersionProductsTestBuild)host.Services.GetRequiredService<IBuildDefinition>()).TestProducts =
        [
            new("AppA")
            {
                Paths = ["src/AppA/**"],
                GitVersionConfig = config,
            },
        ];

        Should
            .Throw<AtomException>(() => host
                .Services
                .GetRequiredService<ProductGitVersionConfigGenerator>()
                .GetExpectedConfigs())
            .Message
            .ShouldStartWith(
                $"The GitVersion configuration of product 'AppA' is the root configuration file '{fileName}'.");
    }

    [Test]
    public void GetExpectedConfigs_WhenAtomRootIsBelowRepositoryRoot_AnchorsIgnoredPathsBelowIt()
    {
        var (host, fileSystem) = CreateHost(gitRepository: false);
        fileSystem.AddDirectory(fileSystem.Path.Combine(fileSystem.Path.GetPathRoot(Root)!, ".git"));

        host
            .Services
            .GetRequiredService<ProductGitVersionConfigGenerator>()
            .GetExpectedConfigs()
            .First(x => x.Product.Name is "AppA")
            .Content
            .ShouldContain(@"    - '^(?!Atom[/\\](?:src[/\\]AppA[/\\].*|");
    }

    [Test]
    public void GetExpectedConfigs_WhenAtomRootIsRepositoryRoot_DoesNotPrefixIgnoredPaths()
    {
        var (host, fileSystem) = CreateHost(gitRepository: false);
        fileSystem.AddFile(fileSystem.Path.Combine(Root, ".git"), new("gitdir: ../.git/worktrees/Atom"));
        fileSystem.AddDirectory(fileSystem.Path.Combine(fileSystem.Path.GetPathRoot(Root)!, ".git"));

        host
            .Services
            .GetRequiredService<ProductGitVersionConfigGenerator>()
            .GetExpectedConfigs()
            .First(x => x.Product.Name is "AppA")
            .Content
            .ShouldBe(ExpectedAppAConfig);
    }

    [Test]
    public void GitVersionConfig_WithProduct_DefaultsToProductConfig()
    {
        var (host, _) = CreateHost(product: "appa");

        ((IGitVersion)host.Services.GetRequiredService<IBuildDefinition>())
            .GitVersionConfig
            .ShouldBe("src/AppA/GitVersion.yml");
    }

    [Test]
    public void GitVersionConfig_WithProductAndExplicitConfig_UsesExplicitConfig()
    {
        var (host, _) = CreateHost(product: "AppA", gitVersionConfig: "other.yml");

        ((IGitVersion)host.Services.GetRequiredService<IBuildDefinition>())
            .GitVersionConfig
            .ShouldBe("other.yml");
    }

    [Test]
    public void GitVersionConfig_WithoutProduct_IsEmpty()
    {
        var (host, _) = CreateHost();

        ((IGitVersion)host.Services.GetRequiredService<IBuildDefinition>())
            .GitVersionConfig
            .ShouldBe(string.Empty);
    }

    [TestCase("a: 1\ntag-prefix: x\nb: 2", "a: 1\nb: 2")]
    [TestCase("ignore:\n  sha: []\n\n  commits-before: 2020\nnext: 1", "next: 1")]
    [TestCase("tag-prefix : x\n# comment\nignore:", "# comment")]
    [TestCase("tag-prefixes: x\nignored: y", "tag-prefixes: x\nignored: y")]
    [TestCase("branches:\n  main:\n    tag-prefix: x", "branches:\n  main:\n    tag-prefix: x")]
    [TestCase("a: 1\nignore:\n#  sha:\n#    - 0123\n  commits-before: 2021\nb: 2", "a: 1\nb: 2")]
    [TestCase("ignore:\n# x\n  commits-before: 2021\nb: 2", "b: 2")]
    [TestCase("ignore:\n  sha: []\n# About b\nb: 2", "# About b\nb: 2")]
    [TestCase("a: 1\nignore:\n  sha: []\n---\nc: 3", "a: 1\n---\nc: 3")]
    [TestCase("a: 1\nignore:\n  sha: []\n# trailing", "a: 1\n# trailing")]
    [TestCase("\"tag-prefix\": v\n'ignore':\n  sha: []\nb: 2", "b: 2")]
    public void RemoveTopLevelKeys_RemovesOnlyTopLevelBlocks(string content, string expected) =>
        ProductGitVersionConfigGenerator
            .RemoveTopLevelKeys(content, ["tag-prefix", "ignore"])
            .ShouldBe(expected);
}
